                            .map { file -> [ [ id: 'exclude' ], file ] }
                input[3] = channel.of('chr19:45760000-45770300\\t45761000\\t45762000\\tchr19_bogus_exp\\t0')
                            .collectFile(name: 'expected_cn.bed', newLine: false)
                            .map { file -> [ [ id: 'expected_cn' ], file ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

